package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;
/** Actual window resizes and screenshots on a temporary native goal; restores display settings. */
final class ResponsiveUiChecks {
 static int checks=0;
 static void main(Instrumentation i,Runnable r){Throwable[] error={null};i.runOnMainSync(()->{try{r.run();}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new AssertionError(error[0]);}
 static void require(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 static void shell(Instrumentation i,String command)throws Exception{try(ParcelFileDescriptor p=i.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
 static String setting(Instrumentation i,String key)throws Exception{try(ParcelFileDescriptor p=i.getUiAutomation().executeShellCommand("settings get system "+key);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){return new String(in.readAllBytes()).trim();}}
 static void capture(Instrumentation i,File dir,String name)throws Exception{i.waitForIdleSync();Thread.sleep(350);android.graphics.Bitmap shot=i.getUiAutomation().takeScreenshot();require(shot!=null,"screenshot unavailable");try(FileOutputStream f=new FileOutputStream(new File(dir,name))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}shot.recycle();}
 static void run(Instrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;String id=null,rotation="0",auto="1",font="1.0";boolean old=i.getTargetContext().getSharedPreferences("nubi_display",0).getBoolean("companion_ui",true);
 try(GoalStore store=new GoalStore(i.getTargetContext())){
  rotation=setting(i,"user_rotation");auto=setting(i,"accelerometer_rotation");font=setting(i,"font_scale");String targetFont=((GoalInstrumentation)i).scenario.getString("fontScale",font);shell(i,"settings put system font_scale "+targetFont);Thread.sleep(300);shell(i,"settings put system accelerometer_rotation 0");
  i.getTargetContext().getSharedPreferences("nubi_display",0).edit().putBoolean("companion_ui",true).commit();for(JSONObject oldGoal:store.goals())if(oldGoal.optString("title").equals("INSTRUMENTATION_RESPONSIVE"))store.deleteGoal(oldGoal.optString("id"));id=store.create("fitness","INSTRUMENTATION_RESPONSIVE","운동",0).getString("id");
  a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity activity=a;
  main(i,()->{activity.relay.stop();activity.chat.history=new JSONArray();activity.chat.history.put(activity.chat.message("assistant","안녕! 오늘은 어떤 운동을 해볼까?\n운동 영상과 필요한 준비물을 찾아줄게."));activity.chat.history.put(activity.chat.message("user","처음 시작하는 요가 영상이랑 매트를 찾아줘."));activity.chat.render();activity.chat.input.setText("회전해도 남아야 하는 입력 초안");activity.chat.input.clearFocus();});
  File dir=new File(i.getTargetContext().getCacheDir(),"responsive");dir.mkdirs();JSONArray cases=new JSONArray();
  String[][] layouts={{"phone360","765x1360","0"},{"compact508","1080x1920","0"},{"tablet-portrait","reset","0"},{"tablet-landscape","reset","1"}};
  for(String[] test:layouts){shell(i,"settings put system user_rotation "+test[2]);shell(i,"wm size "+test[1]);Thread.sleep(900);i.waitForIdleSync();NubiCompanionUi u=activity.chat.companion;
   main(i,()->{u.select("대화");activity.chat.input.clearFocus();});i.waitForIdleSync();Thread.sleep(200);
   final JSONObject metrics=new JSONObject();main(i,()->{try{
    require(!activity.isDestroyed(),"activity recreated on resize");require(activity.chat.input.getText().toString().equals("회전해도 남아야 하는 입력 초안"),"draft lost");int width=(int)(u.outer.getWidth()/activity.getResources().getDisplayMetrics().density);boolean expanded=width>=NubiCompanionUi.EXPANDED_DP;
    require((u.sidebar.getVisibility()==View.VISIBLE)==expanded,"sidebar breakpoint "+test[0]);require((u.dock.getVisibility()==View.VISIBLE)!=expanded,"dock breakpoint "+test[0]);
    require(u.composer.getWidth()>0&&u.composer.getWidth()<=u.root.getWidth(),"composer outside viewport");int[] c=new int[2],r=new int[2];u.composer.getLocationOnScreen(c);u.root.getLocationOnScreen(r);require(c[1]+u.composer.getHeight()<=r[1]+u.root.getHeight(),"composer below viewport");require(activity.chat.input.getWidth()>=Ui.dp(activity,120),"input too narrow");TextView purpose=(TextView)u.outer.findViewWithTag("purpose-action");require(purpose.getPaint().measureText(purpose.getText().toString())<=purpose.getWidth()-purpose.getPaddingLeft()-purpose.getPaddingRight(),"purpose text clipped horizontally");require(purpose.getLayout().getHeight()<=purpose.getHeight()-purpose.getPaddingTop()-purpose.getPaddingBottom(),"purpose text clipped vertically");
    ViewGroup row=(ViewGroup)activity.chat.messages.getChildAt(0);require(row.getChildAt(0).getWidth()<=row.getWidth(),"bubble overflow");
    metrics.put("font_scale",activity.getResources().getConfiguration().fontScale);metrics.put("name",test[0]);metrics.put("width_dp",width);metrics.put("sidebar",expanded);metrics.put("composer_width_px",u.composer.getWidth());metrics.put("bubble_width_px",row.getChildAt(0).getWidth());metrics.put("activity_preserved",true);
   }catch(Exception e){throw new RuntimeException(e);}});cases.put(metrics);
   android.graphics.Bitmap shot=i.getUiAutomation().takeScreenshot();require(shot!=null,"screenshot unavailable");try(FileOutputStream f=new FileOutputStream(new File(dir,test[0]+".png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}shot.recycle();
   if(test[0].equals("phone360")){main(i,u::toggleSidebar);capture(i,dir,"phone360-drawer.png");shell(i,"input keyevent 4");Thread.sleep(300);main(i,()->{u.select("대화");activity.chat.input.requestFocus();((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(activity.chat.input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});Thread.sleep(900);i.waitForIdleSync();main(i,()->{int[] loc=new int[2];u.composer.getLocationOnScreen(loc);android.graphics.Rect visible=new android.graphics.Rect();u.outer.getWindowVisibleDisplayFrame(visible);require(visible.height()<u.outer.getResources().getDisplayMetrics().heightPixels-Ui.dp(activity,100),"keyboard did not open");require(loc[1]+u.composer.getHeight()<=visible.bottom,"keyboard covers composer");require(activity.chat.input.getText().toString().equals("회전해도 남아야 하는 입력 초안"),"keyboard lost draft");});capture(i,dir,"phone360-keyboard.png");main(i,()->((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(activity.chat.input.getWindowToken(),0));Thread.sleep(400);}
   main(i,()->u.select("탐색"));i.waitForIdleSync();require(u.sideScroll.getVisibility()==View.VISIBLE,"explore not visible");capture(i,dir,test[0]+"-explore.png");
   main(i,()->u.select("작업"));i.waitForIdleSync();require(u.sideBody.getChildCount()>1,"library content missing");capture(i,dir,test[0]+"-library.png");
   for(String page:new String[]{"캠퍼스","준비물","일정","여행 비교","생활 계획","로컬 모델","웹 브라우저"}){main(i,()->u.select(page));i.waitForIdleSync();main(i,()->{require(u.sidePage.getWidth()<=u.root.getWidth(),"tool outside viewport "+page);require(u.outer.getParent()!=null,"shell detached "+page);});capture(i,dir,test[0]+"-"+page+".png");}

  }
  try(FileWriter f=new FileWriter(new File(dir,"metrics.json"))){f.write(cases.toString(2));}out.putString("stream","PASS "+checks+" responsive resize and navigation checks\n");
 }catch(Throwable t){out.putString("stream","FAIL "+t+"\n");}finally{try{shell(i,"wm size reset");shell(i,"settings put system user_rotation "+rotation);shell(i,"settings put system accelerometer_rotation "+auto);}catch(Exception ignored){}i.getTargetContext().getSharedPreferences("nubi_display",0).edit().putBoolean("companion_ui",old).commit();if(a!=null){GoalAgentActivity close=a;main(i,close::finish);i.waitForIdleSync();}try{shell(i,"settings put system font_scale "+font);}catch(Exception ignored){}if(id!=null)try(GoalStore s=new GoalStore(i.getTargetContext())){s.deleteGoal(id);}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
 }
}
